import sys
import re
from Bio import SeqIO

def calculate_gc_content(sequence):
    """Calculates GC percentage for a given sequence."""
    if not sequence:
        return 0.0
    gc_count = sequence.upper().count('G') + sequence.upper().count('C')
    total_length = len(sequence)
    gc_percentage = (gc_count / total_length) * 100
    return round(gc_percentage, 2)

def extract_gene_tag(header):
    """Extract the gene name from the header string."""
    # Look for patterns like 'gene=TP53'
    match = re.search(r'gene=([^ ]+)', header)
    if match:
        return match.group(1)
    return "UNKNOWN"

def main():
    if len(sys.argv) != 2:
        # Although the prompt implies the argument is provided, good practice handles it.
        sys.exit(1)

    fasta_path = sys.argv[1]

    try:
        for record in SeqIO.parse(fasta_path, "fasta"):
            header = record.id  # In Biopython, record.id is usually the full header string

            # The header might be complex, but we need the tag
            gene_tag = extract_gene_tag(header)

            sequence = str(record.seq)
            gc_percent = calculate_gc_content(sequence)

            # Print the required output format: GENE<TAB>GC
            print(f"{gene_tag}\t{gc_percent}")

    except FileNotFoundError:
        sys.stderr.write(f"Error: File not found at {fasta_path}\n")
        sys.exit(1)
    except Exception as e:
        sys.stderr.write(f"An error occurred: {e}\n")
        sys.exit(1)

if __name__ == "__main__":
    main()
